package com.example.starter.marpol.domain;

/**
 * 排放类型：油类、垃圾、生活污水。
 */
public enum DischargeType {
    /** 油类排放，特殊区域内禁止。 */
    OIL,
    /** 垃圾排放，距最近陆地不得少于 12 海里。 */
    GARBAGE,
    /** 生活污水排放，特殊区域内禁止。 */
    SEWAGE
}

package com.example.starter.marpol.domain;

/**
 * 排放记录版本状态。
 */
public enum RecordStatus {
    /** 最新有效版本，查询默认返回。 */
    ACTIVE,
    /** 被修正取代的历史版本，物理保留、仍可按版本查询。 */
    SUPERSEDED
}

package com.example.starter.marpol.domain;

/**
 * 港口国核查任务状态。
 */
public enum InspectionStatus {
    /** 核查进行中，核查官可逐条确认或标注违规。 */
    OPEN,
    /** 已签发，终态：结论不可修改，重复签发幂等成功。 */
    ISSUED
}

package com.example.starter.marpol.domain;

/**
 * 核查官对单条排放记录的结论。
 */
public enum Conclusion {
    /** 确认（合规或无异议）。 */
    CONFIRMED,
    /** 标注违规，立即生成缺陷项并限期整改。 */
    VIOLATION
}

package com.example.starter.marpol.domain;

/**
 * 缺陷整改状态。
 */
public enum DefectStatus {
    /** 待整改。 */
    OPEN,
    /** 已在期限内（含第 14 个自然日）关闭。 */
    CLOSED,
    /** 逾期未关闭。 */
    OVERDUE
}

